head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.comCd = ""; // 기업코드
scwin.basYymm = ""; // 결산년월

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로드 이벤트 — 팝업 파라미터(comCd/basYymm)를 수신하고 특기사항 내역을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.param = $c.data.getParameter();
        scwin.comCd   = scwin.param.comCd;
        scwin.basYymm = scwin.param.basYymm;
        scwin.search(); // 조회

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00300_P2.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트 (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Close_onclick
 * @description 팝업닫기
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.img_Close_onclick(e);
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00300_P2.img_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_SpeclablContnRes.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 조회조건이 유효하면 true, 아니면 false
 * @hidden N
 * @example scwin.chkValid();
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name search
 * @description 특기사항팝업 조회
 * @returns {void}
 * @hidden N
 * @example await scwin.search();
 */
scwin.search = async function() {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const url = "/api/listing/nice/individual-notes/audit-opinion/remark-detail?kisCd="+scwin.comCd+"&acntclsDt="+scwin.basYymm;
    $c.sbm.setAction(sbm_dlt_SpeclablContn, url);
    await $c.sbm.execute(sbm_dlt_SpeclablContn);
    scwin.appendContents();
};

/**
 * @method
 * @name appendContents
 * @description 컨텐츠 append
 * @returns {void}
 * @hidden N
 * @example scwin.appendContents();
 */
scwin.appendContents = function() {

    let strContent = "<div style='overflow-x:hidden;width:100%;height:410px;font-family:돋움체;'>";
    for (let nRow = 0; nRow <= dlt_SpeclablContnRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_SpeclablContnRes.getCellData(nRow, "ctnt");
    }
    strContent = strContent + "</div>";

    const grpCtntObj = $p.getComponentById("grp_Ctnt").render;

    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");

};
